<span class="line"><span style="color:#E06C75;font-style:italic;">                        provider</span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;">provider[</span><span style="color:#98C379;">&quot;name&quot;</span><span style="color:#ABB2BF;">],</span></span>
