<span class="line"><span style="color:#E5C07B;">        self</span><span style="color:#ABB2BF;">.base </span><span style="color:#56B6C2;">=</span><span style="color:#61AFEF;"> Path</span><span style="color:#ABB2BF;">(prompts_dir)</span></span>
